script:
// ─────────────────────────────────────────────────────────
// SIDEBAR
// ─────────────────────────────────────────────────────────
const sidebar = document.getElementById('sidebar');
const progressLine = document.getElementById('progressLine');
const overlay = document.getElementById('sbOverlay');
const isMobile = () => window.innerWidth < 768;
const saved = localStorage.getItem('sb-state');
if (saved === 'collapsed' && !isMobile()) { sidebar.classList.add('collapsed'); progressLine.classList.add('visible'); }
function toggleSidebar() {
  if (isMobile()) { const o = sidebar.classList.toggle('open'); overlay.classList.toggle('visible', o); return; }
  const c = sidebar.classList.toggle('collapsed');
  progressLine.classList.toggle('visible', c);
  localStorage.setItem('sb-state', c ? 'collapsed' : 'expanded');
}

// SECTION NAV SCROLL SPY
const la = document.getElementById('lessonArea');
const secIds = [...document.querySelectorAll('section[id]')].map(s => s.id);
document.querySelectorAll('.section-nav a').forEach(a => {
  a.addEventListener('click', e => {
    e.preventDefault();
    const el = document.getElementById(a.getAttribute('href').slice(1));
    if (el) la.scrollTo({ top: el.offsetTop - 48, behavior: 'smooth' });
  });
});
la.addEventListener('scroll', () => {
  const st = la.scrollTop + 60; let cur = secIds[0];
  secIds.forEach(id => { const el = document.getElementById(id); if (el && el.offsetTop <= st) cur = id; });
  document.querySelectorAll('.section-nav a').forEach(a => { a.classList.toggle('active', a.getAttribute('href') === '#' + cur); });
});

// ─────────────────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────────────────
function addLog(logId, msg, cls = '') {
  const log = document.getElementById(logId);
  const d = document.createElement('div');
  d.className = 'log-entry ' + cls;
  d.textContent = msg;
  log.appendChild(d);
  log.scrollTop = log.scrollHeight;
}
function clearLog(logId) { document.getElementById(logId).innerHTML = ''; }

// ─────────────────────────────────────────────────────────
// LINEAR SEARCH ANIMATION
// ─────────────────────────────────────────────────────────
const LINEAR_ARR = [7, 12, 18, 24, 31, 42, 55, 63, 73, 81, 88, 91];
let linStep = -1, linTarget = 42, linRunning = false, linTimer = null;

function getLinearCanvas() { return document.getElementById('linearCanvas'); }

function drawLinear(highlightIdx = -1, foundIdx = -1) {
  const canvas = getLinearCanvas();
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const W = canvas.offsetWidth, H = canvas.offsetHeight;
  canvas.width = W * dpr; canvas.height = H * dpr;
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, W, H);
  const n = LINEAR_ARR.length;
  const cellW = (W - 20) / n, cellH = 52, startY = (H - cellH) / 2;
  LINEAR_ARR.forEach((val, i) => {
    const x = 10 + i * cellW;
    let bg = '#1a2a4d';
    if (i === foundIdx) bg = '#1a4d1a';
    else if (i === highlightIdx) bg = '#4d2a00';
    else if (i < highlightIdx) bg = '#12192e';
    ctx.fillStyle = bg;
    ctx.beginPath(); ctx.roundRect(x + 2, startY, cellW - 4, cellH, 6); ctx.fill();
    ctx.strokeStyle = i === foundIdx ? '#7ef0a0' : i === highlightIdx ? '#ffd580' : '#2a4070';
    ctx.lineWidth = i === highlightIdx || i === foundIdx ? 2 : 1;
    ctx.beginPath(); ctx.roundRect(x + 2, startY, cellW - 4, cellH, 6); ctx.stroke();
    ctx.fillStyle = i === foundIdx ? '#7ef0a0' : i === highlightIdx ? '#ffd580' : '#7a9ad0';
    ctx.font = `bold ${Math.min(13, cellW * 0.4)}px DM Mono, monospace`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(val, x + cellW / 2, startY + cellH / 2);
    ctx.fillStyle = '#445';
    ctx.font = `${9}px DM Mono, monospace`;
    ctx.fillText(i, x + cellW / 2, startY + cellH + 10);
  });
  if (highlightIdx >= 0 && highlightIdx < n) {
    ctx.fillStyle = '#ffd580';
    ctx.font = 'bold 10px DM Sans, sans-serif';
    ctx.textAlign = 'center';
    const ax = 10 + highlightIdx * cellW + cellW / 2;
    ctx.fillText('▲', ax, startY - 8);
  }
}

function linearStart() {
  const t = parseInt(document.getElementById('linearTarget').value);
  linTarget = t; linStep = -1;
  clearLog('linearLog');
  drawLinear();
  document.getElementById('linearStatus').textContent = 'Buscando ' + t + '...';
  addLog('linearLog', 'Iniciando busca por ' + t + ' em lista de ' + LINEAR_ARR.length + ' elementos.');
  linRunning = true;
  document.getElementById('linearPlayBtn').textContent = '⏸ Pausar';
  linearTick();
}

function linearTick() {
  if (!linRunning) return;
  linStep++;
  if (linStep >= LINEAR_ARR.length) {
    drawLinear(linStep - 1);
    addLog('linearLog', '✗ Elemento ' + linTarget + ' não encontrado. Passos: ' + LINEAR_ARR.length, 'rejected');
    document.getElementById('linearStatus').textContent = linStep + ' comparações — NÃO ENCONTRADO';
    linRunning = false;
    document.getElementById('linearPlayBtn').textContent = '▶ Reiniciar';
    return;
  }
  const val = LINEAR_ARR[linStep];
  if (val === linTarget) {
    drawLinear(-1, linStep);
    addLog('linearLog', '✓ Encontrado ' + val + ' na posição ' + linStep + '. Passos: ' + (linStep + 1), 'found');
    document.getElementById('linearStatus').textContent = (linStep + 1) + ' comparações — ENCONTRADO ✓';
    linRunning = false;
    document.getElementById('linearPlayBtn').textContent = '▶ Reiniciar';
    return;
  }
  drawLinear(linStep);
  addLog('linearLog', 'Passo ' + (linStep + 1) + ': comparando ' + val + ' com ' + linTarget + ' → diferente, continua');
  linTimer = setTimeout(linearTick, 500);
}

function linearReset() {
  linRunning = false; linStep = -1;
  clearTimeout(linTimer);
  clearLog('linearLog');
  addLog('linearLog', 'Escolha um alvo e clique em Iniciar.');
  document.getElementById('linearStatus').textContent = '—';
  document.getElementById('linearPlayBtn').textContent = '▶ Iniciar';
  setTimeout(() => drawLinear(), 50);
}

// ─────────────────────────────────────────────────────────
// BINARY SEARCH ANIMATION
// ─────────────────────────────────────────────────────────
let binArr = [], binLo = 0, binHi = 0, binTarget = 0, binStep = 0, binRunning = false, binTimer = null;

function buildBinArr(size) {
  const arr = [];
  let v = 3;
  for (let i = 0; i < size; i++) { arr.push(v); v += Math.floor(Math.random() * 8) + 3; }
  return arr;
}

function binaryReset() {
  binRunning = false; clearTimeout(binTimer);
  const size = parseInt(document.getElementById('binarySize').value);
  binArr = buildBinArr(size);
  binLo = 0; binHi = size - 1; binStep = 0;
  clearLog('binaryLog');
  addLog('binaryLog', 'Lista de ' + size + ' elementos gerada. Escolha o alvo e clique em Iniciar.');
  document.getElementById('binaryStatus').textContent = '—';
  document.getElementById('binaryPlayBtn').textContent = '▶ Iniciar';
  setTimeout(() => drawBinary(0, binArr.length - 1, -1, -1), 50);
}

function drawBinary(lo, hi, mid, foundIdx) {
  const canvas = document.getElementById('binaryCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const W = canvas.offsetWidth, H = canvas.offsetHeight;
  canvas.width = W * dpr; canvas.height = H * dpr;
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, W, H);
  const n = binArr.length;
  const cellW = (W - 20) / n, cellH = 48, startY = (H - cellH - 20) / 2;
  binArr.forEach((val, i) => {
    const x = 10 + i * cellW;
    let bg = '#12192e', border = '#1a2a4d';
    if (i === foundIdx) { bg = '#1a4d1a'; border = '#7ef0a0'; }
    else if (i === mid) { bg = '#4d2a00'; border = '#ffd580'; }
    else if (i < lo || i > hi) { bg = '#0a0f1e'; border = '#111'; }
    else { bg = '#1a2a4d'; border = '#2a4070'; }
    ctx.fillStyle = bg;
    ctx.beginPath(); ctx.roundRect(x + 1, startY, cellW - 2, cellH, 4); ctx.fill();
    ctx.strokeStyle = border;
    ctx.lineWidth = i === mid || i === foundIdx ? 2 : 1;
    ctx.beginPath(); ctx.roundRect(x + 1, startY, cellW - 2, cellH, 4); ctx.stroke();
    if (i >= lo && i <= hi || i === foundIdx) {
      ctx.fillStyle = i === foundIdx ? '#7ef0a0' : i === mid ? '#ffd580' : '#6a8ac0';
      ctx.font = `bold ${Math.min(11, cellW * 0.42)}px DM Mono, monospace`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(val > 99 ? '…' : val, x + cellW / 2, startY + cellH / 2);
    }
  });
  // Labels
  if (mid >= 0 && mid < n) {
    ctx.fillStyle = '#ffd580'; ctx.font = 'bold 9px DM Sans, sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('meio', 10 + mid * cellW + cellW / 2, startY + cellH + 12);
  }
}

function binaryStart() {
  const size = parseInt(document.getElementById('binarySize').value);
  const tType = document.getElementById('binaryTarget').value;
  let target;
  if (tType === 'found-start') target = binArr[0];
  else if (tType === 'found-end') target = binArr[binArr.length - 1];
  else target = binArr[binArr.length - 1] + 5;
  binTarget = target; binLo = 0; binHi = binArr.length - 1; binStep = 0;
  clearLog('binaryLog');
  addLog('binaryLog', 'Buscando ' + target + ' em lista de ' + size + ' elementos.');
  document.getElementById('binaryStatus').textContent = 'Buscando ' + target + '...';
  binRunning = true;
  document.getElementById('binaryPlayBtn').textContent = '⏸ Pausar';
  binTimer = setTimeout(binaryTick, 600);
}

function binaryTick() {
  if (!binRunning) return;
  if (binLo > binHi) {
    drawBinary(binLo, binHi, -1, -1);
    addLog('binaryLog', '✗ ' + binTarget + ' não encontrado. Total de passos: ' + binStep, 'rejected');
    document.getElementById('binaryStatus').textContent = binStep + ' passos — NÃO ENCONTRADO';
    binRunning = false; document.getElementById('binaryPlayBtn').textContent = '▶ Reiniciar'; return;
  }
  const mid = Math.floor((binLo + binHi) / 2);
  binStep++;
  drawBinary(binLo, binHi, mid, -1);
  if (binArr[mid] === binTarget) {
    drawBinary(binLo, binHi, -1, mid);
    addLog('binaryLog', '✓ Encontrado na posição ' + mid + '. Total: ' + binStep + ' passo(s)', 'found');
    document.getElementById('binaryStatus').textContent = binStep + ' passo(s) — ENCONTRADO ✓';
    binRunning = false; document.getElementById('binaryPlayBtn').textContent = '▶ Reiniciar'; return;
  }
  if (binArr[mid] < binTarget) {
    addLog('binaryLog', 'Passo ' + binStep + ': meio[' + mid + ']=' + binArr[mid] + ' < ' + binTarget + ' → descarta metade esquerda');
    binLo = mid + 1;
  } else {
    addLog('binaryLog', 'Passo ' + binStep + ': meio[' + mid + ']=' + binArr[mid] + ' > ' + binTarget + ' → descarta metade direita');
    binHi = mid - 1;
  }
  binTimer = setTimeout(binaryTick, 700);
}

// ─────────────────────────────────────────────────────────
// BUBBLE SORT ANIMATION
// ─────────────────────────────────────────────────────────
let bArr = [], bI = 0, bJ = 0, bSwaps = 0, bComps = 0, bDone = false, bRunTimer = null;

function shuffleArr(n) {
  const a = Array.from({length: n}, (_, i) => (i + 1) * Math.floor(100 / n));
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

function bubbleReset() {
  clearTimeout(bRunTimer);
  const n = parseInt(document.getElementById('bubbleSize').value);
  bArr = shuffleArr(n); bI = 0; bJ = 0; bSwaps = 0; bComps = 0; bDone = false;
  clearLog('bubbleLog');
  addLog('bubbleLog', 'Array de ' + n + ' elementos gerado. Clique "Próximo passo" para iniciar.');
  document.getElementById('bubbleStatus').textContent = '—';
  setTimeout(() => drawBubble(-1, -1, bArr.length), 50);
}

function drawBubble(j1, j2, sortedFrom) {
  const canvas = document.getElementById('bubbleCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const W = canvas.offsetWidth, H = canvas.offsetHeight;
  canvas.width = W * dpr; canvas.height = H * dpr;
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, W, H);
  const n = bArr.length;
  const maxVal = Math.max(...bArr);
  const barW = (W - 20) / n;
  const maxH = H - 36;
  bArr.forEach((val, i) => {
    const bh = (val / maxVal) * maxH;
    const x = 10 + i * barW;
    const y = H - bh - 18;
    let color = '#1a3a6e';
    if (i >= sortedFrom) color = '#1a4d2a';
    else if (i === j1 || i === j2) color = '#6e2a00';
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.roundRect(x + 1, y, barW - 2, bh, 3); ctx.fill();
    if (i === j1 || i === j2) {
      ctx.strokeStyle = '#ffd580'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.roundRect(x + 1, y, barW - 2, bh, 3); ctx.stroke();
    }
    ctx.fillStyle = i >= sortedFrom ? '#7ef0a0' : i === j1 || i === j2 ? '#ffd580' : '#4a6a9a';
    ctx.font = `${Math.min(10, barW * 0.6)}px DM Mono, monospace`;
    ctx.textAlign = 'center';
    ctx.fillText(val, x + barW / 2, H - 5);
  });
}

function bubbleStep() {
  if (bDone) { bubbleReset(); return; }
  if (bArr.length === 0) { bubbleReset(); return; }
  const n = bArr.length;
  if (bI >= n - 1) {
    drawBubble(-1, -1, 0);
    addLog('bubbleLog', '✓ Ordenado! Total: ' + bComps + ' comparações, ' + bSwaps + ' trocas.', 'found');
    document.getElementById('bubbleStatus').textContent = bComps + ' comparações · ' + bSwaps + ' trocas';
    bDone = true; return;
  }
  if (bJ >= n - 1 - bI) { bI++; bJ = 0; }
  if (bI >= n - 1) { bubbleStep(); return; }
  const sortedFrom = n - bI;
  bComps++;
  if (bArr[bJ] > bArr[bJ + 1]) {
    [bArr[bJ], bArr[bJ + 1]] = [bArr[bJ + 1], bArr[bJ]];
    bSwaps++;
    addLog('bubbleLog', 'Passo ' + bComps + ': trocou ' + bArr[bJ + 1] + '↔' + bArr[bJ] + ' (posições ' + bJ + ' e ' + (bJ + 1) + ')');
  } else {
    addLog('bubbleLog', 'Passo ' + bComps + ': ' + bArr[bJ] + '≤' + bArr[bJ + 1] + ' — sem troca');
  }
  drawBubble(bJ, bJ + 1, sortedFrom);
  document.getElementById('bubbleStatus').textContent = bComps + ' comps · ' + bSwaps + ' trocas · passagem ' + (bI + 1);
  bJ++;
}

function bubbleRunAll() {
  if (bDone) { bubbleReset(); return; }
  const maxSteps = 500;
  let steps = 0;
  while (!bDone && steps < maxSteps) { bubbleStep(); steps++; }
}

// ─────────────────────────────────────────────────────────
// MERGE SORT TREE VISUALIZATION
// ─────────────────────────────────────────────────────────
let treeLevel = -1, treeN = 8;

function treeReset() {
  treeN = parseInt(document.getElementById('treeSize').value);
  document.getElementById('treeSizeLabel').textContent = treeN;
  treeLevel = -1;
  renderTree();
}

function treeStep() {
  const maxLevels = Math.log2(treeN);
  if (treeLevel < maxLevels) { treeLevel++; renderTree(); }
}

function treeRunAll() {
  treeLevel = Math.log2(treeN);
  renderTree();
}

function renderTree() {
  const container = document.getElementById('treeContainer');
  if (!container) return;
  // log2(n) = número de vezes que dividimos por 2 até chegar em 1
  // Ex: n=16 → 16,8,4,2,1 = 4 divisões = log2(16) = 4
  // Níveis que fazem MERGE: 0..log2(n)-1 (cada um custa n operações)
  // Nível base (log2(n)): arrays de 1 elemento — nada a mergear, custo 0
  const mergeLevels = Math.log2(treeN); // quantas divisões até chegar em 1
  const totalLevels = mergeLevels + 1;  // +1 para o nível base (tamanho 1)
  let html = '';
  let cumulativeWork = 0;

  for (let level = 0; level < totalLevels; level++) {
    const nodesAtLevel = Math.pow(2, level);
    const sizeAtLevel = treeN / nodesAtLevel;
    const isBase = level === mergeLevels;
    const workAtLevel = isBase ? 0 : treeN; // base não faz merge
    const visible = level <= treeLevel;

    const workLabel = isBase
      ? (visible ? '0 (caso base — sem merge)' : '—')
      : (visible ? treeN + ' operações' : '—');
    const labelColor = isBase ? '#7ef0a0' : '#ffd580';

    html += `<div class="tree-level-label" style="opacity:${visible ? 1 : 0.2}">
      <span>Nível ${level}: ${nodesAtLevel} ${nodesAtLevel === 1 ? 'lista' : 'listas'} de ${sizeAtLevel} ${sizeAtLevel === 1 ? 'elemento (base)' : 'elementos'}</span>
      <span style="font-family:var(--fm);color:${labelColor}">${workLabel}</span>
    </div>`;
    html += '<div class="tree-level">';
    for (let i = 0; i < nodesAtLevel; i++) {
      const cls = isBase ? 'n-green' : 'n-blue';
      html += `<div class="tree-node ${cls}" style="opacity:${visible ? 1 : 0.15}">${sizeAtLevel}</div>`;
    }
    html += '</div>';
    if (visible) cumulativeWork += workAtLevel;
  }

  if (treeLevel >= 0) {
    const isComplete = treeLevel >= mergeLevels;
    const levelsWithWork = Math.min(treeLevel, mergeLevels); // só conta os que fazem merge
    html += `<div class="tree-total-bar" style="opacity:1">
      <span>${isComplete ? '✓ Total completo' : (treeLevel + 1) + ' de ' + totalLevels + ' níveis'}</span>
      <span>${cumulativeWork} operações${isComplete ? ' = <strong>' + treeN + ' × ' + mergeLevels + ' = ' + cumulativeWork + '</strong>' : ''}</span>
    </div>`;
    if (isComplete) {
      html += `<div class="callout success" style="margin-top:.8rem">
        <strong>De onde vem o ${mergeLevels}?</strong>
        Para n=${treeN}, dividimos por 2 até chegar em 1:
        ${Array.from({length: mergeLevels + 1}, (_, i) => treeN / Math.pow(2, i)).join(' → ')}
        — são <strong>${mergeLevels} divisões</strong>, ou seja, log₂(${treeN}) = ${mergeLevels}.<br><br>
        Cada um dos ${mergeLevels} níveis de merge faz exatamente <strong>${treeN} operações</strong> no total.<br>
        <strong>Custo total = ${treeN} operações × ${mergeLevels} níveis = ${cumulativeWork}</strong><br><br>
        Em F1.3 você vai ver a equação T(n) = 2T(n/2) + n que descreve exatamente esse padrão — e chegará a n·log₂(n) formalmente.
      </div>`;
    }
  }

  container.innerHTML = html;
}

// ─────────────────────────────────────────────────────────
// QUICKSORT ANIMATION (partition step-by-step)
// ─────────────────────────────────────────────────────────
let qArr = [], qPivotIdx = -1, qLo = 0, qHi = 0, qI = -1, qJ = 0;
let qDone = false, qComps = 0, qSwaps = 0, qPhase = 'start';
// qPhase: 'start' | 'partition' | 'recurse' | 'done'
let qStack = []; // stack of [lo, hi] sub-arrays to process
let qSorted = new Set();
let qCurrentPivot = -1;

function buildQuickArr(mode) {
  if (mode === 'worst') return [2, 4, 6, 8, 10, 12, 14, 16]; // already sorted → pivot first = worst case
  if (mode === 'first') return [14, 3, 9, 1, 7, 11, 5, 16];
  return [7, 14, 3, 11, 1, 9, 5, 16]; // middle pivot tends to be good
}

function quickReset() {
  const mode = document.getElementById('quickPivotMode').value;
  qArr = buildQuickArr(mode);
  qSorted = new Set(); qDone = false; qComps = 0; qSwaps = 0;
  qCurrentPivot = -1;
  // Initialize stack with full array
  qStack = [[0, qArr.length - 1]];
  qPhase = 'start';
  clearLog('quickLog');
  const modeLabel = mode === 'worst' ? 'pior caso (lista já ordenada, pivô = primeiro)' :
                    mode === 'first' ? 'pivô = primeiro elemento' : 'pivô = elemento do meio';
  addLog('quickLog', 'Array: [' + qArr.join(', ') + '] · modo: ' + modeLabel);
  addLog('quickLog', 'Clique "Próximo passo" para ver o particionamento.');
  document.getElementById('quickStatus').textContent = '—';
  setTimeout(() => drawQuick(-1, -1, -1), 50);
}

function drawQuick(lo, hi, pivotIdx) {
  const canvas = document.getElementById('quickCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const W = canvas.offsetWidth, H = canvas.offsetHeight;
  canvas.width = W * dpr; canvas.height = H * dpr;
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, W, H);
  const n = qArr.length;
  const maxVal = Math.max(...qArr);
  const barW = (W - 20) / n;
  const maxH = H - 36;
  qArr.forEach((val, i) => {
    const bh = (val / maxVal) * maxH;
    const x = 10 + i * barW;
    const y = H - bh - 18;
    let color = '#1a2a4d';
    if (qSorted.has(i)) color = '#1a4d2a';
    else if (i === pivotIdx) color = '#5a2a00';
    else if (lo >= 0 && i >= lo && i <= hi) color = '#1a3060';
    else if (lo >= 0) color = '#0e1628';
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.roundRect(x + 1, y, barW - 2, bh, 3); ctx.fill();
    let stroke = qSorted.has(i) ? '#7ef0a0' : i === pivotIdx ? '#ffd580' :
                 (lo >= 0 && i >= lo && i <= hi) ? '#2a4a90' : '#151e30';
    ctx.strokeStyle = stroke;
    ctx.lineWidth = (i === pivotIdx || qSorted.has(i)) ? 2 : 1;
    ctx.beginPath(); ctx.roundRect(x + 1, y, barW - 2, bh, 3); ctx.stroke();
    ctx.fillStyle = qSorted.has(i) ? '#7ef0a0' : i === pivotIdx ? '#ffd580' :
                    (lo >= 0 && i >= lo && i <= hi) ? '#6a8ac0' : '#2a3a5a';
    ctx.font = `${Math.min(11, barW * 0.55)}px DM Mono, monospace`;
    ctx.textAlign = 'center';
    ctx.fillText(val, x + barW / 2, H - 5);
  });
  // Pivot label
  if (pivotIdx >= 0 && pivotIdx < n) {
    ctx.fillStyle = '#ffd580';
    ctx.font = 'bold 9px DM Sans, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('pivô', 10 + pivotIdx * barW + barW / 2, H - bh_forLabel(pivotIdx, maxVal, maxH, H) - 22);
  }
}
function bh_forLabel(i, maxVal, maxH, H) { return (qArr[i] / maxVal) * maxH; }

function partitionStep() {
  // Single partition: pick pivot, do full partition, push sub-arrays to stack
  if (qStack.length === 0) {
    // all done
    for (let i = 0; i < qArr.length; i++) qSorted.add(i);
    drawQuick(-1, -1, -1);
    addLog('quickLog', '✓ Array ordenado! ' + qComps + ' comparações, ' + qSwaps + ' trocas.', 'found');
    document.getElementById('quickStatus').textContent = qComps + ' comps · ' + qSwaps + ' trocas · ORDENADO ✓';
    qDone = true; return;
  }
  const [lo, hi] = qStack.pop();
  if (lo >= hi) {
    if (lo === hi) qSorted.add(lo);
    partitionStep(); return;
  }
  const mode = document.getElementById('quickPivotMode').value;
  let pivotIdx;
  if (mode === 'worst' || mode === 'first') pivotIdx = lo;
  else pivotIdx = Math.floor((lo + hi) / 2);

  // Move pivot to end
  [qArr[pivotIdx], qArr[hi]] = [qArr[hi], qArr[pivotIdx]]; qSwaps++;
  const pivotVal = qArr[hi];

  addLog('quickLog', '── Particionando [' + lo + '…' + hi + '] · pivô = ' + pivotVal);
  drawQuick(lo, hi, hi);

  // Partition in place
  let storeIdx = lo;
  for (let k = lo; k < hi; k++) {
    qComps++;
    if (qArr[k] <= pivotVal) {
      [qArr[k], qArr[storeIdx]] = [qArr[storeIdx], qArr[k]]; qSwaps++;
      storeIdx++;
    }
  }
  [qArr[storeIdx], qArr[hi]] = [qArr[hi], qArr[storeIdx]]; qSwaps++;
  qSorted.add(storeIdx);
  addLog('quickLog', '   Pivô ' + pivotVal + ' → posição ' + storeIdx + ' · menores: [' + lo + '…' + (storeIdx-1) + '] · maiores: [' + (storeIdx+1) + '…' + hi + ']');

  drawQuick(lo, hi, storeIdx);

  // Push sub-problems
  if (storeIdx - 1 > lo) qStack.push([lo, storeIdx - 1]);
  else if (storeIdx - 1 === lo) qSorted.add(lo);
  if (storeIdx + 1 < hi) qStack.push([storeIdx + 1, hi]);
  else if (storeIdx + 1 === hi) qSorted.add(hi);

  document.getElementById('quickStatus').textContent = qComps + ' comps · ' + qSwaps + ' trocas · ' + qStack.length + ' sub-array(s) restante(s)';
}

function quickStep() {
  if (qDone) { quickReset(); return; }
  if (qArr.length === 0) { quickReset(); return; }
  partitionStep();
}

function quickRunAll() {
  if (qDone) { quickReset(); return; }
  const max = 200;
  let i = 0;
  while (!qDone && i++ < max) partitionStep();
}

